            //
            aWandererK = aWandererK ^ (((RotL64(aIngress, 30U) + RotL64(aOrbiterG, 3U)) + aOrbiterF) + aPhaseDWandererUpdateSaltE[(((31U - aIndex) + 25U)) & S_SALT1]);
