            //
            aOrbiterI = (aWandererK + RotL64(aScatter, 35U)) + 0xE030ADF2B9E7EAD6ULL;
            aOrbiterE = (aWandererE + RotL64(aIngress, 41U)) + 0x541D6A457C235723ULL;
            aOrbiterB = ((aWandererC + RotL64(aCross, 27U)) + RotL64(aCarry, 19U)) + 0x913A45F406D92975ULL;
