            aOrbiterD = ((aWandererB + RotL64(aCross, 21U)) + 0x9E63A1E891E9FCD5ULL) + aPhaseBOrbiterAssignSaltF[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterF = (((aWandererF + RotL64(aIngress, 51U)) + RotL64(aCarry, 35U)) + 0x6C5F1061568C46B3ULL) + aPhaseBOrbiterAssignSaltE[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterA = (aWandererJ + RotL64(aScatter, 13U)) + 0x66E1DD285EA834F1ULL;
            //
            aOrbiterI = (aOrbiterI + aOrbiterE) + 0xD72CBA82AA05360AULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterI) ^ 0x2E499DBB0A484519ULL) ^ aPhaseBOrbiterUpdateSaltD[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x29920DBB65A4AEF9ULL), 3U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterB) + 0xD97640D89391F3D2ULL) + aPhaseBOrbiterUpdateSaltA[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterK) ^ 0x85BC980D78523705ULL;
