            //
            aOrbiterF = (aOrbiterF + aOrbiterI) + 0xDBC832F7314930C2ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterF) ^ 0x2ADA9E8A82A614CDULL;
            aOrbiterK = RotL64((aOrbiterK * 0xAAB8E4DDB6D5A0F5ULL), 41U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterK) + 0x6CEC737F0FD1BD9BULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterA) ^ 0x714A41A77DBB5866ULL) ^ aPhaseBOrbiterUpdateSaltB[(((31U - aIndex) + 13U)) & S_SALT1];
