            //
            aOrbiterB = ((aOrbiterB + aOrbiterF) + 0x7391D9DCD5634A86ULL) + aPhaseBOrbiterUpdateSaltE[((aIndex + 11U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0x13B84E269ECC8DF9ULL;
