            aWandererI = aWandererI + (((RotL64(aScatter, 47U) + aOrbiterA) + RotL64(aOrbiterE, 53U)) + aPhaseBWandererUpdateSaltD[(((31U - aIndex) + 27U)) & S_SALT1]);
            aWandererF = aWandererF ^ (((RotL64(aCross, 11U) + aOrbiterA) + RotL64(aOrbiterK, 27U)) + aPhaseBWandererUpdateSaltA[((aIndex + 17U)) & S_SALT1]);
            aWandererJ = aWandererJ + ((RotL64(aPrevious, 23U) + aOrbiterB) + RotL64(aOrbiterK, 13U));
            //
